cd /home/user/fortress/explorations/reviews/batch-6.5b-review && cat > distance_tie.py <<'EOF'
"""Tie climb batch 6.5b's distance move (627 -> 624) to its edits by comparing the two committed per-site
tables, batch N's gate and 6.5b's gate, with no stage run. Each site's location is mapped through the line
maps of the two files the batch changed that the stage reads (Library/FortressLibrary.fss, +3 below V's
insertions; ProjectFortress/LibraryBuiltin/FortressBuiltin.fss, V's edit), computed with difflib from git
over 382b9fe7f..e3214cbf1, and the (kind, family, subclass, unit, message-with-positions-masked) of each site
compared as a multiset.  python3 distance_tie.py > distance-tie.txt"""
import collections, difflib, re, subprocess
REPO = '/home/user/fortress'
A = REPO + '/explorations/compile-ladder/climb-batch-N/gate/distance-sites.tsv'
B = REPO + '/explorations/compile-ladder/climb-batch-6.5b/gate/distance-sites.tsv'
FILES = {'FortressLibrary.fss': 'Library/FortressLibrary.fss',
         'FortressBuiltin.fss': 'ProjectFortress/LibraryBuiltin/FortressBuiltin.fss',
         'RangeInternals.fss': 'Library/RangeInternals.fss',
         'FortressLibrary.fsi': 'Library/FortressLibrary.fsi',
         'FortressBuiltin.fsi': 'ProjectFortress/LibraryBuiltin/FortressBuiltin.fsi'}
def show(rev, path):
    return subprocess.run(['git', '-C', REPO, 'show', f'{rev}:{path}'], capture_output=True, text=True).stdout.splitlines()
maps = {}
for short, path in FILES.items():
    a, b = show('382b9fe7f', path), show('e3214cbf1', path)
    m = {}
    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if tag == 'equal':
            for k in range(i2 - i1): m[i1 + k + 1] = j1 + k + 1
    maps[short] = m
def remap(text):
    def sub(mo):
        f, line = mo.group(1), int(mo.group(2))
        if f in maps:
            n = maps[f].get(line)
            return f'{f}:{n}' if n else f'{f}:?{line}'
        return mo.group(0)
    return re.sub(r'(\w+\.fs[si]):(\d+)', sub, text)
def mask(text):
    return re.sub(r'(\w+\.fs[si]):\??\d+(?::\d+)?(?:-\d+(?::\d+)?)?(?:\.\d+)?', r'\1:L', text)
def rows(path, remapped):
    out = []
    for l in open(path):
        if l.startswith('#') or not l.strip(): continue
        c = l.rstrip('\n').split('\t')
        loc, msg = c[5], c[6]
        if remapped: loc, msg = remap(loc), remap(msg)
        out.append((c[0], c[1], c[2], c[3], loc, msg))
    return out
ra, rb = rows(A, True), rows(B, False)
ka = collections.Counter(r for r in ra); kb = collections.Counter(r for r in rb)
gone = ka - kb; new = kb - ka
print('batch N sites %d, 6.5b sites %d; after mapping N\'s locations to the landed tree: %d gone, %d new' % (len(ra), len(rb), sum(gone.values()), sum(new.values())))
km = collections.Counter((r[0], r[1], r[2], r[3], mask(r[5])) for r in ra); kbm = collections.Counter((r[0], r[1], r[2], r[3], mask(r[5])) for r in rb)
print('masking every position as well: %d gone, %d new' % (sum((km - kbm).values()), sum((kbm - km).values())))
print('\n== gone (in batch N\'s table, not in 6.5b\'s), N\'s locations mapped to the landed tree')
for r, n in sorted(gone.items()):
    print('%dx %s\t%s\t%s\t%s\t%s\n     %s' % (n, r[0], r[1], r[2], r[3], r[4], r[5][:330]))
print('\n== new (in 6.5b\'s table, not in batch N\'s)')
for r, n in sorted(new.items()):
    print('%dx %s\t%s\t%s\t%s\t%s\n     %s' % (n, r[0], r[1], r[2], r[3], r[4], r[5][:330]))
EOF
PYTHONDONTWRITEBYTECODE=1 python3 distance_tie.py > distance-tie.txt; head -60 distance-tie.txt

